import os
import torch


class Config:
    # =========================================================================
    # Reproducibility
    # =========================================================================
    SEED = 42

    # =========================================================================
    # File Paths
    # =========================================================================
    # Input Metadata (Generated by previous steps)
    METADATA_DIR = "./metadata"
    TRAIN_METADATA = os.path.join(METADATA_DIR, "train.csv")
    VAL_METADATA = os.path.join(METADATA_DIR, "val.csv")
    TEST_METADATA = os.path.join(METADATA_DIR, "test.csv")

    # Input Images
    INPUT_DIR = "./input"
    TRAIN_IMG_DIR = os.path.join(INPUT_DIR, "train_images")
    TEST_IMG_DIR = os.path.join(INPUT_DIR, "test_images")

    # Working Directory (for Checkpoints and Cache)
    WORKING_DIR = "./working/idea_11"
    CACHE_DIR = WORKING_DIR  # Directory to store cached processed data
    MODEL_PATH = os.path.join(WORKING_DIR, "best_model.pth")

    # Submission Output
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # =========================================================================
    # Model Hyperparameters
    # =========================================================================
    # Architecture: Pyramid Symmetry-Difference Siamese EfficientNet-B2
    BACKBONE = "tf_efficientnet_b2.ns_jft_in1k"
    IMG_SIZE = (768, 768)

    # Input Channels: 1 (Mammogram) + 1 (Age Map) + 1 (Implant Map) = 3
    # This fits standard ImageNet pretrained stride.
    IN_CHANNELS = 3
    NUM_CLASSES = 1

    # =========================================================================
    # Training Hyperparameters
    # =========================================================================
    BATCH_SIZE = 8  # Adjusted for 768x768 Siamese Network on A100 (40GB)
    EPOCHS = 10  # Max epochs (Early stopping should handle termination)
    LEARNING_RATE = 1e-4  # AdamW LR
    WEIGHT_DECAY = 1e-2  # AdamW Weight Decay

    # Loss Configuration
    # Aggressive positive weighting to approximate inverse class frequency (ratio ~47)
    POS_WEIGHT = 47.0

    # Gradient Strategy
    MAX_GRAD_NORM = None  # Gradient clipping disabled as per strategy

    # =========================================================================
    # Compute & Environment
    # =========================================================================
    NUM_WORKERS = 4  # Number of dataloader workers (12 vCPUs available)
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    # =========================================================================
    # Debugging / Development
    # =========================================================================
    # Set DEBUG to True to run on a small subset of data for rapid testing
    DEBUG = False
    DEBUG_SAMPLE_SIZE = 500

    @classmethod
    def setup(cls):
        """
        Creates the necessary working and submission directories.
        Should be called at the start of the execution.
        """
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)
        print(f"Directories ensured: {cls.WORKING_DIR}, {cls.SUBMISSION_DIR}")
